renderHTML.render:
function (element, view) {
  if (typeof echarts === 'undefined') return null;
  var read = function (name, fallback) {
    var v = element.a(name);
    if (v === undefined || v === null || v === '') return fallback;
    if (typeof v === 'string') { try { return JSON.parse(v); } catch (e) { return fallback; } }
    return v;
  };
  var dom = document.createElement('div');
  dom.style.cssText = 'width:100%;height:100%;';
  var chart = echarts.init(dom);
  // echarts 首帧可能在宿主布局完成前测量尺寸，下一帧强制校正
  var ro = new ResizeObserver(function () { chart.resize(); });
  ro.observe(dom);
  requestAnimationFrame(function () { chart.resize(); });
  var apply = function () {
    chart.setOption({
      color: read('color', ['#5470c6', '#91cc75', '#fac858', '#ee6666', '#73c0de']),
      title: { text: element.a('title') || '', left: 'center', textStyle: { fontSize: 14 } },
      tooltip: { trigger: 'item' },
      legend: { show: element.a('showLegend') !== false, top: 34, left: 'center' },
      series: [{
        type: 'pie',
        radius: ['35%', '60%'],
        center: ['50%', '52%'],
        data: read('data', []),
        label: { fontSize: 11 }
      }]
    }, { notMerge: true });
  };
  apply();
  dom.__chart = chart;
  dom.__apply = apply;
  dom.__ro = ro;
  return dom;
}

renderHTML.update:
function (dom, element) {
  if (dom.__apply) dom.__apply();
  if (dom.__chart) dom.__chart.resize();
}

renderHTML.dispose:
function (dom) {
  if (dom.__ro) dom.__ro.disconnect();
  if (dom.__chart) dom.__chart.dispose();
  dom.__chart = null;
}
